"""Add procedural craters to moon PNGs generated by PlanetGenerator.

Usage:
  python3 dev/add_craters_to_moons.py
"""

import os
import math
import random
import numpy as np
from PIL import Image

MOONS_DIR = os.path.join(
    os.path.dirname(__file__), '..', 'public', 'moons')


def add_craters(img, seed):
    """Overlay procedural craters on a moon image."""
    arr = np.array(img, dtype=np.float32)
    h, w = arr.shape[:2]
    rgba = arr.shape[2] == 4

    # Find the moon disc (alpha > 0 or non-transparent)
    if rgba:
        alpha = arr[:, :, 3] / 255.0
    else:
        alpha = np.ones((h, w), dtype=np.float32)

    # Center of the moon disc
    ys, xs = np.where(alpha > 0.5)
    if len(xs) == 0:
        return img
    cx = xs.mean()
    cy = ys.mean()
    radius = min(
        np.sqrt((xs - cx) ** 2 + (ys - cy) ** 2).max(), w / 2 - 1)

    # Light direction: upper-left
    lx, ly = -0.6, -0.6

    # Add 5-12 craters at random positions on the disc
    rng = random.Random(seed)
    crater_count = 5 + rng.randint(0, 7)

    for _ in range(crater_count):
        # Random position on disc
        uc = (rng.random() - 0.5) * 1.6
        vc = (rng.random() - 0.5) * 1.6
        dist = math.sqrt(uc * uc + vc * vc)
        if dist > 0.80:
            continue
        foreshorten = math.sqrt(max(0, 1 - dist * dist))
        crater_r = radius * (0.06 + rng.random() * 0.14)
        sx = int(cx + uc * radius)
        sy = int(cy + vc * radius)

        x0 = max(0, int(sx - crater_r - 2))
        x1 = min(w, int(sx + crater_r + 2))
        y0 = max(0, int(sy - crater_r - 2))
        y1 = min(h, int(sy + crater_r + 2))

        for py in range(y0, y1):
            for px in range(x0, x1):
                if alpha[py, px] < 0.5:
                    continue
                ddx = px - sx
                ddy = py - sy
                d = math.sqrt(
                    (ddx / crater_r) ** 2 +
                    (ddy / (crater_r * foreshorten)) ** 2)
                if d > 1.0:
                    continue
                if d > 0:
                    pdx = ddx / (crater_r * d)
                    pdy = ddy / (crater_r * d)
                else:
                    pdx = pdy = 0
                dot = pdx * lx + pdy * ly

                # Smooth crater depth: deepest at center, tapering to 0
                depth = max(0, 1.0 - d)

                # Shadow on the side away from light
                shadow_strength = max(0, -dot) * depth

                # Highlight at the rim on the light-facing side
                rim_factor = max(0, d - 0.6) / 0.4
                highlight_strength = max(0, dot) * rim_factor

                # Apply shadow and highlight to RGB
                for c in range(3):
                    val = arr[py, px, c]
                    # Darken by shadow
                    val *= (1.0 - shadow_strength * 0.6)
                    # Brighten by highlight
                    val += highlight_strength * 40
                    arr[py, px, c] = max(0, min(255, val))

    return Image.fromarray(arr.astype(np.uint8), 'RGBA' if rgba else 'RGB')


def main():
    print(f"[CRATERS] Adding craters to moons in {MOONS_DIR}")
    files = sorted(
        f for f in os.listdir(MOONS_DIR)
        if f.startswith('moon_') and f.endswith('.png'))
    print(f"[CRATERS] Found {len(files)} moon PNGs")

    for i, fname in enumerate(files):
        path = os.path.join(MOONS_DIR, fname)
        img = Image.open(path).convert('RGBA')
        seed = int(fname.split('_')[1].split('.')[0]) * 17 + 42
        img = add_craters(img, seed)
        img.save(path)
        if (i + 1) % 10 == 0:
            print(f"  {i + 1}/{len(files)} done")

    print(f"[CRATERS] All {len(files)} moons processed")


if __name__ == '__main__':
    main()
